  $products=collect($rows)->map(function($r,$i)use($category){
   $image=asset('images/themes/baby/'.$r[1].'.png');
   $p=new Product(['title'=>$r[0],'handle'=>'theme-demo-baby-'.$r[1],'brand'=>'JW STUDIO','status'=>'active','subtitle'=>$i===0?'A soft layer for little moments.':'Thoughtful pieces for little moments.','base_price'=>$r[2],'description'=>'<p>A soft layer for little everyday moments.</p>','options'=>[['name'=>'Colour','values'=>[$r[3]],'displayType'=>'pills']]]);$p->id=-200-$i;
   $im=new ProductImage(['path'=>$image,'alt'=>$r[0],'position'=>0]);$im->id=-2000-$i;
   $v=new ProductVariant(['title'=>$r[3],'sku'=>'DEMO-BABY-'.$i,'price'=>$r[2],'stock'=>25,'enabled'=>true,'options'=>['Colour'=>$r[3],'Size'=>'100 x 100 cm']]);$v->id=-2000-$i;$v->setRelation('product',$p);
   $variants=collect([$v]);$images=collect([$im]);
