   return $p->setRelation('category',$category)->setRelation('images',$images)->setRelation('variants',$variants)->setRelation('pdpContent',new ProductPdpContent(['highlights'=>[['id'=>'audio','text'=>'Soft cotton','icon'=>'leaf'],['id'=>'check','text'=>'Lightweight weave','icon'=>'check'],['id'=>'package','text'=>'Everyday comfort','icon'=>'package']],'specifications'=>[['id'=>'driver','label'=>'Material','value'=>'Cotton'],['id'=>'connectivity','label'=>'Weave','value'=>'Muslin'],['id'=>'check','label'=>'Size','value'=>'Lightweight weave'],['id'=>'weight','label'=>'Weight','value'=>'100 x 100 cm']],'custom_accordions'=>[['id'=>'compatibility','title'=>'Care instructions','content'=>'Wash according to the care label.'],['id'=>'box','title'=>"What's in the box",'content'=>'One muslin blanket.'],['id'=>'care','title'=>'Care & support','content'=>'Keep clean and dry.']],'story'=>['heading'=>'Made for their little moments.','description'=>'A soft layer for little everyday moments.','image'=>asset('images/themes/baby/'.($i===0?'blanket-story':'hero').'.png')]]))->setRelation('reviews',collect())->setRelation('pdpRelatedProducts',collect());
  });
  $request->attributes->set('websiteThemeDemoVariants',$products->flatMap(fn($p)=>$p->variants)->all());$request->attributes->set('websiteThemeDemoProducts',$products);
  $min=max(3900,$request->integer('min_price',3900));$max=min(8900,$request->integer('max_price',8900));$sort=$request->input('sort','');$colors=array_values(array_filter((array)$request->input('color',[]),'is_string'));$visible=$products->filter(fn($p)=>$p->base_price>=$min&&$p->base_price<=$max);$visible=$visible->filter(fn($p)=>$colors===[]||$p->variants->contains(fn($v)=>in_array(strtolower($v->title),$colors,true)));if($sort==='price_asc')$visible=$visible->sortBy('base_price');if($sort==='price_desc')$visible=$visible->sortByDesc('base_price');
  $filters=['search'=>'','category'=>null,'sort'=>$sort,'layout'=>'grid','minPrice'=>$min,'maxPrice'=>$max,'boundsMinPrice'=>3900,'boundsMaxPrice'=>8900,'priceRequested'=>$min!==3900||$max!==8900,'inStock'=>$request->boolean('in_stock'),'colors'=>$colors,'materials'=>[],'minRating'=>0,'variantFiltered'=>false];
  $facets=['priceBounds'=>['min'=>3900,'max'=>8900],'total'=>6,'categoryCounts'=>[-2=>6],'colors'=>[['value'=>'oat','label'=>'Oat','hex'=>'#cfc3b3','count'=>2],['value'=>'sage','label'=>'Sage','hex'=>'#a5ae95','count'=>3]],'materials'=>[],'hasRatings'=>false,'ratings'=>[]];
  return (new CatalogFilterResult($filters,new LengthAwarePaginator($visible->values(),$visible->count(),12),$facets))->toViewData()+['demoTheme'=>'baby','categories'=>collect([$category]),'collection'=>null,'listingCategory'=>$category,'catalogListingSettings'=>['title'=>$category->name,'description'=>$category->description],'listingRouteName'=>'admin.website-design.preview','listingRouteParameters'=>['theme'=>'baby','surface'=>'plp'],'demoProducts'=>$products];
 }
